const f = ref({ action: route.query.action || '', actor: route.query.actor || '', target: route.query.target || '', from: route.query.from || '', to: route.query.to || '' });
const list = usePaged('/api/admin/audit', { key: 'entries', limit: 50, extraQuery: () => ({ ...f.value }) });
let t = null;
