</script>

<template>
  <div>
    <div class="page-head"><div><h1>Журнал действий</h1><div class="sub">{{ list.total.value }} записей</div></div></div>
    <div class="row wrap mb-16"><input class="input" v-model="f.action" placeholder="Действие (напр. admin.)" style="max-width: 200px" /><input class="input" v-model="f.actor" placeholder="Кто (e-mail / канал)" style="max-width: 200px" /><input class="input" v-model="f.target" placeholder="ID объекта" style="max-width: 200px" /><input class="input" type="date" v-model="f.from" style="max-width: 160px" /><input class="input" type="date" v-model="f.to" style="max-width: 160px" /></div>
    <div class="table-wrap"><table class="table"><thead><tr><th>Время</th><th>Кто</th><th>Действие</th><th>Объект</th><th>Детали</th><th>IP</th></tr></thead><tbody>
      <tr v-for="e in list.items.value" :key="e.id"><td class="small nowrap">{{ fmtDateTime(e.createdAt) }}</td><td class="small"><router-link v-if="e.actor" :to="`/admin/users/${e.actor.id}`">{{ e.actor.name }}</router-link><span v-else class="muted">система</span></td><td><span class="badge" :class="e.action.startsWith('admin.') ? 'brand' : ''">{{ LABELS[e.action] || e.action }}</span></td><td class="small mono">{{ e.targetType }} {{ e.targetId ? e.targetId.slice(0, 12) : '' }}</td><td class="tiny mono" style="max-width: 360px; white-space: pre-wrap; word-break: break-all">{{ Object.keys(e.details || {}).length ? JSON.stringify(e.details) : '' }}</td><td class="small mono">{{ e.ip }}</td></tr>
      <tr v-if="!list.items.value.length"><td colspan="6" class="muted">Записей нет</td></tr>
    </tbody></table></div>
    <Pagination :page="list.page.value" :total="list.total.value" :limit="50" @change="list.setPage" />
  </div>
</template>
